import React, { useState, useEffect, useMemo } from 'react';
import { askText } from '../../components/AppFeedback';
import Layout from '../../components/Layout';
import { PageTitle, StatCards, Card, Btn, Badge, Field, ProgressBar, SearchBar } from '../../components/Shared';
import { Building2, Users, Briefcase, MapPin, Plus, BrainCircuit, TrendingUp, TrendingDown, AlertTriangle, Sparkles, User, Bell, Shield, CreditCard, CheckCircle, X, School, CalendarDays, UserCog, IndianRupee, MessageSquareText, Plug, Database, Save, Upload, KeyRound, Smartphone, Mail, ReceiptIndianRupee, Clock3, FileText, Download, LockKeyhole, Globe2, Palette, ChevronRight, CheckCircle2, CloudCog, History, RefreshCcw, Crown, GraduationCap, Wallet, CalendarCheck, Activity, Network, BarChart3, Radio, Search } from 'lucide-react';
import { LineChart, Line, BarChart, Bar, PieChart, Pie, Cell, XAxis, YAxis, Tooltip, ResponsiveContainer, CartesianGrid } from 'recharts';
import api from '../../api';
import { useAuth } from '../../context/AuthContext';
import { useNavigate } from 'react-router-dom';

const money = (value) => `₹${Number(value || 0).toLocaleString('en-IN', { maximumFractionDigits: 0 })}`;
const metric = (value, suffix = '%') => value === null || value === undefined ? 'Awaiting data' : `${value}${suffix}`;

const BranchDetail = ({ branch, canManage = false, onEdit, onStatus, onOpen, onFix }) => {
  if (!branch) return null;
  return <div className="space-y-5">
    <div className="overflow-hidden rounded-3xl bg-gradient-to-br from-[#0B1535] via-[#202C64] to-[#4F46E5] p-6 text-white shadow-[0_24px_55px_rgba(30,41,99,0.22)]">
      <div className="flex flex-wrap items-start justify-between gap-4">
        <div className="flex items-start gap-4"><span className="flex h-12 w-12 items-center justify-center rounded-2xl bg-white/10 ring-1 ring-white/15"><School className="h-6 w-6" /></span><div><div className="flex flex-wrap items-center gap-2"><h3 className="font-poppins text-[20px] font-bold">{branch.name}</h3><span className="rounded-full bg-white/10 px-2.5 py-1 text-[12px] font-bold uppercase tracking-wider">{branch.code}</span></div><p className="mt-1 flex items-center gap-1.5 text-[13px] text-indigo-100"><MapPin className="h-3.5 w-3.5" />{branch.city}{branch.academic_year ? ` · ${branch.academic_year}` : ''}</p></div></div>
        <div className="flex flex-wrap items-center justify-end gap-2"><Badge color={branch.status === 'Active' ? 'green' : branch.status === 'Suspended' ? 'red' : 'amber'}>{branch.status}</Badge>{branch.status !== 'Suspended' && <Btn variant="outline" icon={Building2} onClick={() => onOpen?.('/dashboard')}>Open Workspace</Btn>}{canManage && <Btn variant="outline" icon={UserCog} onClick={onEdit}>Edit Branch</Btn>}{canManage && branch.status !== 'Active' && <Btn icon={CheckCircle2} onClick={() => onStatus?.('Active')}>Activate</Btn>}{canManage && branch.status === 'Active' && branch.id !== 'BR-MAIN' && <Btn variant="outline" icon={LockKeyhole} onClick={() => onStatus?.('Suspended')}>Suspend</Btn>}</div>
      </div>
      <div className="mt-6 grid grid-cols-2 gap-3 md:grid-cols-4">{[
        ['Students', branch.students, Users], ['People', branch.people, Briefcase],
        ['Attendance', metric(branch.attendance_rate), CalendarCheck], ['Capacity', branch.capacity ? `${branch.students}/${branch.capacity}` : 'Not set', Building2],
      ].map(([label,value,Icon]) => <div key={label} className="rounded-2xl border border-white/10 bg-white/[0.07] p-3.5"><Icon className="mb-3 h-4 w-4 text-cyan-200"/><b className="block text-[18px]">{value}</b><small className="text-[12px] uppercase tracking-wider text-indigo-200">{label}</small></div>)}</div>
    </div>
    <div className="grid grid-cols-1 gap-5 xl:grid-cols-2">
      <Card title="Branch readiness" subtitle={`${branch.setup_progress}% of the branch operating setup is complete.`}>
        <ProgressBar value={branch.setup_progress || 0}/>
        <div className="mt-5 space-y-2">{(branch.setup_checks || []).map(item => <div key={item.key} className="flex items-center gap-3 rounded-xl bg-slate-50 px-3.5 py-3"><span className={`flex h-7 w-7 items-center justify-center rounded-lg ${item.complete ? 'bg-emerald-100 text-emerald-700' : 'bg-amber-100 text-amber-700'}`}>{item.complete ? <CheckCircle2 className="h-4 w-4"/> : <Clock3 className="h-4 w-4"/>}</span><span className="text-[13px] font-semibold text-slate-700">{item.label}</span>{!item.complete && canManage ? <button onClick={() => onFix?.(item.key)} className="ml-auto rounded-lg bg-white px-2.5 py-1.5 text-[12px] font-bold text-indigo-600 shadow-sm ring-1 ring-slate-100">Fix now</button> : <span className="ml-auto text-[12px] font-bold uppercase text-slate-400">{item.complete ? 'Complete' : 'Pending'}</span>}</div>)}</div>
      </Card>
      <Card title="Management attention" subtitle="Only genuine risks from this branch are shown.">
        <div className="space-y-3">{(branch.risks || []).map((risk,index) => <div key={`${risk.label}-${index}`} className={`flex items-center gap-3 rounded-2xl border p-4 ${risk.level === 'High' ? 'border-rose-100 bg-rose-50' : risk.level === 'Clear' ? 'border-emerald-100 bg-emerald-50' : 'border-amber-100 bg-amber-50'}`}><AlertTriangle className={`h-5 w-5 ${risk.level === 'High' ? 'text-rose-600' : risk.level === 'Clear' ? 'text-emerald-600' : 'text-amber-600'}`}/><div><b className="text-[13px] text-slate-800">{risk.label}</b><p className="mt-0.5 text-[12px] text-slate-500">{risk.level} priority</p></div></div>)}</div>
        <div className="mt-5 grid grid-cols-2 gap-3"><div className="rounded-2xl bg-slate-50 p-4"><p className="text-[12px] uppercase text-slate-400">Fee outstanding</p><b className="mt-1 block text-[17px] text-slate-900">{money(branch.outstanding)}</b></div><div className="rounded-2xl bg-slate-50 p-4"><p className="text-[12px] uppercase text-slate-400">Current-month attendance</p><b className="mt-1 block text-[17px] text-slate-900">{metric(branch.attendance_rate)}</b><small className="text-[12px] text-slate-400">{branch.metric_period || 'Current month'}</small></div></div>
      </Card>
    </div>
    <Card title="Connected role apps" subtitle="The branch is the data boundary; every app receives only its assigned campus records.">
      <div className="grid grid-cols-1 gap-3 md:grid-cols-3">{(branch.app_connections || []).map((app,index) => { const Icon = index === 0 ? Smartphone : index === 1 ? GraduationCap : Crown; return <div key={app.name} className="rounded-2xl border border-slate-100 bg-gradient-to-br from-white to-indigo-50/50 p-4"><span className="mb-4 flex h-9 w-9 items-center justify-center rounded-xl bg-indigo-100 text-indigo-700"><Icon className="h-4 w-4"/></span><b className="text-[13px] text-slate-900">{app.name}</b><p className="mt-1 text-[12px] leading-4 text-slate-500">{app.purpose}</p></div>})}</div>
    </Card>
  </div>;
};

export const MultiBranch = ({ mode = 'overview' }) => {
  const { auth, setActiveBranch } = useAuth();
  const navigate = useNavigate();
  const canManage = auth?.role === 'admin';
  const [networkData, setNetworkData] = useState({ summary: {}, branches: [], governance: {} });
  const [selectedId, setSelectedId] = useState('BR-MAIN');
  const [query, setQuery] = useState('');
  const [adding, setAdding] = useState(false);
  const [editing, setEditing] = useState(false);
  const [loading, setLoading] = useState(true);
  const [notice, setNotice] = useState('');
  const [error, setError] = useState('');
  const emptyDraft = { name:'', code:'', city:'', address:'', phone:'', email:'', principal_name:'', academic_year:'', board:'CBSE', capacity:'' };
  const [draft, setDraft] = useState(emptyDraft);
  const [editDraft, setEditDraft] = useState(emptyDraft);
  const [accessAssignments, setAccessAssignments] = useState([]);
  const [reportStatus, setReportStatus] = useState('All');
  const [reportYear, setReportYear] = useState('All');
  const load = async () => { setLoading(true); setError(''); try { const [{ data }, accessResult] = await Promise.all([api.get('/branches/network'), api.get('/branch-access-assignments').catch(() => ({ data:[] }))]); setNetworkData(data || { summary:{}, branches:[] }); setAccessAssignments(accessResult.data || []); if (!selectedId && data?.branches?.[0]) setSelectedId(data.branches[0].id); } catch (err) { setError(err.response?.data?.detail || 'Could not load the branch network.'); } finally { setLoading(false); } };
  // Load once when this workspace opens. Manual refreshes use the same loader.
  // eslint-disable-next-line react-hooks/exhaustive-deps
  useEffect(() => { load(); }, []);
  const branches = useMemo(() => networkData.branches || [], [networkData.branches]);
  const selected = branches.find(branch => branch.id === selectedId) || branches[0];
  const filtered = useMemo(() => { const term = query.trim().toLowerCase(); return term ? branches.filter(branch => [branch.name, branch.code, branch.city, branch.principal_name].some(value => String(value || '').toLowerCase().includes(term))) : branches; }, [branches, query]);
  const reportRows = useMemo(() => branches.filter(branch => (reportStatus === 'All' || branch.status === reportStatus) && (reportYear === 'All' || branch.academic_year === reportYear)), [branches, reportStatus, reportYear]);
  const reportYears = useMemo(() => [...new Set(branches.map(branch => branch.academic_year).filter(Boolean))].sort(), [branches]);
  const createBranch = async (event) => { event.preventDefault(); setError(''); try { const { data } = await api.post('/branches', { ...draft, capacity:Number(draft.capacity || 0) }); setDraft(emptyDraft); setAdding(false); setSelectedId(data.id); setNotice(`${data.name} was created in Setup mode. Complete the readiness checklist before operations begin.`); await load(); } catch (err) { setError(err.response?.data?.detail || 'Could not create this branch.'); } };
  const startEdit = () => { if (!selected) return; setEditDraft({ ...emptyDraft, ...selected, capacity:selected.capacity || '' }); setEditing(true); };
  const updateBranch = async (event) => { event.preventDefault(); if (!selected) return; setError(''); try { await api.put(`/branches/${selected.id}`, { ...editDraft, capacity:Number(editDraft.capacity || 0) }); setEditing(false); setNotice(`${selected.name} was updated.`); await load(); } catch (err) { setError(err.response?.data?.detail || 'Could not update this branch.'); } };
  const updateStatus = async (status) => { if (!selected) return; const status_reason = status === 'Suspended' ? await askText('Why is this branch being suspended?') : ''; if (status === 'Suspended' && !status_reason?.trim()) return; setError(''); try { await api.put(`/branches/${selected.id}`, { status, status_reason }); setNotice(`${selected.name} is now ${status}.`); await load(); } catch (err) { setError(err.response?.data?.detail || `Could not change this branch to ${status}.`); } };
  const openWorkspace = (path = '/dashboard') => { if (!selected) return; setActiveBranch({ id:selected.id, name:selected.name, code:selected.code }); navigate(path); window.location.reload(); };
  const fixSetup = (key) => { if (key === 'profile' || key === 'leadership') { startEdit(); return; } const paths = { academics:'/academics', people:'/teachers/view', finance:'/fee/create' }; openWorkspace(paths[key] || '/dashboard'); };
  const saveAccess = async (staffRole, branchIds) => { try { await api.put(`/branch-access-assignments/${staffRole}`, { branch_ids:branchIds }); setNotice(`${staffRole.replaceAll('_',' ')} branch access was updated. It applies on the next login.`); await load(); } catch (err) { setError(err.response?.data?.detail || 'Could not update branch access.'); } };
  const toggleAccess = (staffRole, branchId) => { const current = accessAssignments.find(item => item.role === staffRole)?.branch_ids || ['BR-MAIN']; const next = current.includes(branchId) ? current.filter(id => id !== branchId) : [...current, branchId]; if (!next.length) { setError('Assign at least one branch to this role.'); return; } saveAccess(staffRole, next); };
  const downloadReport = () => { const columns = ['Branch','Code','Status','Academic Year','Students','Capacity','Academic Average','Attendance','Fee Collection','Outstanding','Expenses','Health']; const rows = reportRows.map(branch => [branch.name,branch.code,branch.status,branch.academic_year,branch.students,branch.capacity,branch.academic_average ?? '',branch.attendance_rate ?? '',branch.collection_efficiency,branch.outstanding,branch.expenses,branch.health_score]); const csv = [columns, ...rows].map(row => row.map(value => `"${String(value ?? '').replaceAll('"','""')}"`).join(',')).join('\n'); const blob = new Blob([csv], { type:'text/csv;charset=utf-8' }); const url = URL.createObjectURL(blob); const link = document.createElement('a'); link.href=url; link.download=`orison-branch-report-${new Date().toISOString().slice(0,10)}.csv`; link.click(); URL.revokeObjectURL(url); };
  const summary = networkData.summary || {};
  const title = mode === 'directory' ? 'Branch Directory' : mode === 'reports' ? 'Consolidated Branch Reports' : 'Multi Branch Control Centre';
  const subtitle = mode === 'directory' ? 'Create campuses, assign branch leadership and monitor setup readiness.' : mode === 'reports' ? 'Compare genuine academic, finance, attendance and operational outcomes across campuses.' : 'One trusted network view for Admin and Director—without mixing branch-level student or staff data.';
  return <Layout>
    <PageTitle title={title} subtitle={subtitle} actions={<div className="flex gap-2"><Btn variant="outline" icon={RefreshCcw} onClick={load}>{loading ? 'Refreshing…' : 'Refresh'}</Btn>{canManage && mode !== 'reports' && <Btn icon={Plus} onClick={() => setAdding(value => !value)}>Add Branch</Btn>}</div>}/>
    {error && <div className="mb-5 flex items-center justify-between rounded-2xl border border-rose-100 bg-rose-50 px-4 py-3 text-[13px] text-rose-700"><span>{error}</span><button onClick={()=>setError('')}><X className="h-4 w-4"/></button></div>}
    {notice && <div className="mb-5 flex items-center justify-between rounded-2xl border border-emerald-100 bg-emerald-50 px-4 py-3 text-[13px] text-emerald-700"><span className="flex items-center gap-2"><CheckCircle className="h-4 w-4"/>{notice}</span><button onClick={()=>setNotice('')}><X className="h-4 w-4"/></button></div>}
    {adding && <Card title="Create a new branch" subtitle="Student and staff counts are never typed manually; they will be calculated from live branch records." className="mb-6"><form onSubmit={createBranch} className="grid grid-cols-1 gap-4 md:grid-cols-2 xl:grid-cols-4"><Field label="Branch name" value={draft.name} onChange={e=>setDraft({...draft,name:e.target.value})} placeholder="e.g. Orison North Campus"/><Field label="Unique branch code" value={draft.code} onChange={e=>setDraft({...draft,code:e.target.value})} placeholder="e.g. ORI-NORTH"/><Field label="City" value={draft.city} onChange={e=>setDraft({...draft,city:e.target.value})} placeholder="City"/><Field label="Academic year" value={draft.academic_year} onChange={e=>setDraft({...draft,academic_year:e.target.value})} placeholder="2026–27"/><Field label="Principal / branch head" value={draft.principal_name} onChange={e=>setDraft({...draft,principal_name:e.target.value})} placeholder="Leadership name"/><Field label="Board" value={draft.board} onChange={e=>setDraft({...draft,board:e.target.value})} placeholder="CBSE / State Board"/><Field label="Phone" value={draft.phone} onChange={e=>setDraft({...draft,phone:e.target.value})} placeholder="Branch contact"/><Field label="Email" type="email" value={draft.email} onChange={e=>setDraft({...draft,email:e.target.value})} placeholder="Branch email"/><Field label="Capacity" type="number" value={draft.capacity} onChange={e=>setDraft({...draft,capacity:e.target.value})} placeholder="Planned student capacity"/><div className="md:col-span-2 xl:col-span-3"><Field label="Address" value={draft.address} onChange={e=>setDraft({...draft,address:e.target.value})} placeholder="Complete campus address"/></div><div className="md:col-span-2 xl:col-span-4 flex gap-2"><Btn type="submit" icon={Plus}>Create in Setup Mode</Btn><Btn variant="outline" onClick={()=>setAdding(false)}>Cancel</Btn></div></form></Card>}
    {editing && selected && <Card title={`Edit ${selected.name}`} subtitle="Keep branch leadership, contact information and capacity accurate." className="mb-6"><form onSubmit={updateBranch} className="grid grid-cols-1 gap-4 md:grid-cols-2 xl:grid-cols-4"><Field label="Branch name" value={editDraft.name || ''} onChange={e=>setEditDraft({...editDraft,name:e.target.value})}/><Field label="City" value={editDraft.city || ''} onChange={e=>setEditDraft({...editDraft,city:e.target.value})}/><Field label="Principal / branch head" value={editDraft.principal_name || ''} onChange={e=>setEditDraft({...editDraft,principal_name:e.target.value})}/><Field label="Board" value={editDraft.board || ''} onChange={e=>setEditDraft({...editDraft,board:e.target.value})}/><Field label="Phone" value={editDraft.phone || ''} onChange={e=>setEditDraft({...editDraft,phone:e.target.value})}/><Field label="Email" type="email" value={editDraft.email || ''} onChange={e=>setEditDraft({...editDraft,email:e.target.value})}/><Field label="Student capacity" type="number" value={editDraft.capacity || ''} onChange={e=>setEditDraft({...editDraft,capacity:e.target.value})}/><Field label="Address" value={editDraft.address || ''} onChange={e=>setEditDraft({...editDraft,address:e.target.value})}/><div className="md:col-span-2 xl:col-span-4 flex gap-2"><Btn type="submit" icon={Save}>Save Branch</Btn><Btn variant="outline" onClick={()=>setEditing(false)}>Cancel</Btn></div></form></Card>}

    {mode === 'overview' && <>
      <div className="relative mb-6 overflow-hidden rounded-[28px] bg-gradient-to-br from-[#081126] via-[#172554] to-[#4338CA] px-7 py-7 text-white shadow-[0_25px_60px_rgba(30,41,99,0.22)]"><div className="absolute -right-20 -top-28 h-72 w-72 rounded-full bg-cyan-400/15 blur-3xl"/><div className="relative flex flex-col justify-between gap-7 xl:flex-row xl:items-end"><div><div className="mb-4 inline-flex items-center gap-2 rounded-full border border-white/10 bg-white/[0.07] px-3 py-1.5 text-[12px] font-bold uppercase tracking-[0.14em] text-cyan-100"><Network className="h-3.5 w-3.5"/>Live institution network</div><h3 className="max-w-2xl font-poppins text-[26px] font-bold leading-tight">Every campus visible.<br/>Every role accountable.</h3><p className="mt-3 max-w-xl text-[13px] leading-5 text-indigo-100/75">Current ERP records are protected under Main Campus. New branches receive isolated operational ownership and app routing.</p></div><div className="grid grid-cols-2 gap-3 md:grid-cols-4">{[['Active campuses',`${summary.active_branches || 0}/${summary.branches || 0}`],['Students',(summary.students || 0).toLocaleString()],['Network attendance',metric(summary.attendance_rate)],['Fee efficiency',metric(summary.collection_efficiency)]].map(([label,value])=><div key={label} className="min-w-[125px] rounded-2xl border border-white/10 bg-white/[0.08] p-3.5"><b className="text-[18px]">{value}</b><p className="mt-1 text-[12px] uppercase tracking-wider text-indigo-200">{label}</p></div>)}</div></div></div>
      <StatCards items={[{ label:'Total Branches',value:summary.branches || 0,icon:Building2 },{ label:'Students Across Network',value:(summary.students || 0).toLocaleString(),icon:Users,tint:'bg-blue-50 text-blue-600' },{ label:'Teachers & Staff',value:(summary.people || 0).toLocaleString(),icon:Briefcase,tint:'bg-emerald-50 text-emerald-600' },{ label:'Network Outstanding',value:money(summary.outstanding),icon:IndianRupee,tint:'bg-amber-50 text-amber-600' }]}/>
      <div className="mb-6 grid grid-cols-1 gap-6 xl:grid-cols-[1.35fr_.65fr]"><Card title="Campus performance" subtitle="Select a branch to inspect its live health and readiness."><div className="space-y-2">{branches.map(branch => <button key={branch.id} onClick={()=>setSelectedId(branch.id)} className={`grid w-full grid-cols-[1fr_auto] items-center gap-4 rounded-2xl border p-4 text-left transition md:grid-cols-[1fr_90px_90px_90px_auto] ${selected?.id === branch.id ? 'border-indigo-200 bg-indigo-50/70 shadow-sm' : 'border-slate-100 hover:bg-slate-50'}`}><div className="flex min-w-0 items-center gap-3"><span className="flex h-9 w-9 shrink-0 items-center justify-center rounded-xl bg-white text-indigo-600 shadow-sm"><Building2 className="h-4 w-4"/></span><div className="min-w-0"><b className="block truncate text-[13px] text-slate-900">{branch.name}</b><span className="text-[12px] text-slate-400">{branch.city} · {branch.code}</span></div></div><div className="hidden md:block"><b className="text-[13px] text-slate-800">{branch.students}</b><p className="text-[12px] text-slate-400">Students</p></div><div className="hidden md:block"><b className="text-[13px] text-slate-800">{metric(branch.attendance_rate)}</b><p className="text-[12px] text-slate-400">Attendance</p></div><div className="hidden md:block"><b className="text-[13px] text-slate-800">{branch.health_score}%</b><p className="text-[12px] text-slate-400">Health</p></div><ChevronRight className="h-4 w-4 text-slate-400"/></button>)}</div></Card><Card title="Management queue" subtitle="Network-level matters needing leadership attention."><div className="space-y-3">{branches.flatMap(branch => (branch.risks || []).filter(r=>r.level === 'High').map(r=>({...r,branch:branch.name}))).slice(0,5).map((risk,index)=><div key={`${risk.branch}-${index}`} className="rounded-2xl border border-rose-100 bg-rose-50 p-4"><div className="flex items-center gap-2 text-rose-700"><AlertTriangle className="h-4 w-4"/><b className="text-[12px]">{risk.label}</b></div><p className="mt-1.5 pl-6 text-[12px] text-rose-500">{risk.branch}</p></div>)}{!branches.some(branch=>(branch.risks || []).some(r=>r.level === 'High')) && <div className="rounded-2xl border border-emerald-100 bg-emerald-50 p-5 text-center"><CheckCircle2 className="mx-auto h-6 w-6 text-emerald-600"/><b className="mt-2 block text-[13px] text-emerald-800">No critical network risk</b><p className="mt-1 text-[12px] text-emerald-600">Branch operations are within current thresholds.</p></div>}<div className="grid grid-cols-2 gap-3 pt-2"><div className="rounded-2xl bg-slate-50 p-4"><b className="text-[18px] text-slate-900">{summary.pending_approvals || 0}</b><p className="text-[12px] text-slate-400">Director approvals</p></div><div className="rounded-2xl bg-slate-50 p-4"><b className="text-[18px] text-slate-900">{money(summary.fees_collected)}</b><p className="text-[12px] text-slate-400">Network collection</p></div></div></div></Card></div>
      <BranchDetail branch={selected} canManage={canManage} onEdit={startEdit} onStatus={updateStatus} onOpen={openWorkspace} onFix={fixSetup}/>
    </>}

    {mode === 'directory' && <div className="space-y-6"><div className="grid grid-cols-1 gap-6 xl:grid-cols-[.78fr_1.22fr]"><Card title="All branches" subtitle="Search by campus, code, city or branch head." className="self-start"><SearchBar value={query} onChange={e=>setQuery(e.target.value)} placeholder="Search branch directory..." className="mb-4"/><div className="space-y-2">{filtered.map(branch=><button key={branch.id} onClick={()=>setSelectedId(branch.id)} className={`w-full rounded-2xl border p-4 text-left transition ${selected?.id===branch.id?'border-indigo-200 bg-indigo-50':'border-slate-100 hover:bg-slate-50'}`}><div className="flex items-start justify-between gap-3"><div><b className="text-[13px] text-slate-900">{branch.name}</b><p className="mt-1 flex items-center gap-1 text-[12px] text-slate-400"><MapPin className="h-3 w-3"/>{branch.city} · {branch.code}</p></div><Badge color={branch.status==='Active'?'green':branch.status==='Suspended'?'red':'amber'}>{branch.status}</Badge></div><div className="mt-4 flex items-center gap-3"><ProgressBar value={branch.setup_progress || 0}/><span className="shrink-0 text-[12px] font-bold text-slate-500">{branch.setup_progress}% ready</span></div></button>)}</div></Card><BranchDetail branch={selected} canManage={canManage} onEdit={startEdit} onStatus={updateStatus} onOpen={openWorkspace} onFix={fixSetup}/></div><Card title="Branch access by staff role" subtitle="Admin controls which campus each operational login can open. Admin and Director retain network-wide access."><div className="grid grid-cols-1 gap-4 xl:grid-cols-2">{['academic_coordinator','fee_manager'].map(staffRole=>{const assigned=accessAssignments.find(item=>item.role===staffRole)?.branch_ids || ['BR-MAIN'];return <div key={staffRole} className="rounded-2xl border border-slate-100 bg-slate-50/70 p-4"><div className="mb-4 flex items-center gap-3"><span className="flex h-9 w-9 items-center justify-center rounded-xl bg-indigo-100 text-indigo-700"><UserCog className="h-4 w-4"/></span><div><b className="text-[13px] capitalize text-slate-900">{staffRole.replaceAll('_',' ')}</b><p className="text-[12px] text-slate-400">{assigned.length} branch assignment(s)</p></div></div><div className="flex flex-wrap gap-2">{branches.filter(branch=>branch.status!=='Suspended').map(branch=><button disabled={!canManage} onClick={()=>toggleAccess(staffRole,branch.id)} key={branch.id} className={`rounded-xl px-3 py-2 text-[12px] font-bold transition ${assigned.includes(branch.id)?'bg-indigo-600 text-white':'bg-white text-slate-500 ring-1 ring-slate-200'} disabled:cursor-not-allowed`}>{assigned.includes(branch.id)?'✓ ':''}{branch.name}</button>)}</div></div>})}</div></Card></div>}

    {mode === 'reports' && <div className="space-y-6"><StatCards items={[{label:'Fee Expected',value:money(summary.fees_expected),icon:Wallet},{label:'Fee Collected',value:money(summary.fees_collected),icon:IndianRupee,tint:'bg-emerald-50 text-emerald-600'},{label:'Network Attendance',value:metric(summary.attendance_rate),icon:CalendarCheck,tint:'bg-blue-50 text-blue-600'},{label:'Pending Approvals',value:summary.pending_approvals || 0,icon:Shield,tint:'bg-amber-50 text-amber-600'}]}/><Card title="Report filters" subtitle="Choose the campuses to compare, then download the same view for management review."><div className="flex flex-col gap-3 md:flex-row md:items-end"><label className="flex-1 text-[12px] font-bold uppercase tracking-wider text-slate-400">Branch status<select value={reportStatus} onChange={e=>setReportStatus(e.target.value)} className="mt-2 h-11 w-full rounded-xl border border-slate-200 bg-white px-3 text-[13px] font-semibold text-slate-700"><option>All</option><option>Active</option><option>Setup</option><option>Suspended</option></select></label><label className="flex-1 text-[12px] font-bold uppercase tracking-wider text-slate-400">Academic year<select value={reportYear} onChange={e=>setReportYear(e.target.value)} className="mt-2 h-11 w-full rounded-xl border border-slate-200 bg-white px-3 text-[13px] font-semibold text-slate-700"><option>All</option>{reportYears.map(year=><option key={year}>{year}</option>)}</select></label><Btn icon={Download} onClick={downloadReport}>Download CSV</Btn></div></Card><Card title="Branch outcome comparison" subtitle="Academic average uses published marks; attendance uses the current month; zero means no operational record exists." pad="p-0"><div className="overflow-x-auto"><table className="w-full min-w-[980px] text-left"><thead><tr className="border-b border-slate-100 bg-slate-50 text-[12px] uppercase tracking-wider text-slate-400">{['Branch','Students','Academic avg.','Attendance','Fee collection','Outstanding','Expenses','Health'].map(label=><th key={label} className="px-5 py-3 font-semibold">{label}</th>)}</tr></thead><tbody>{reportRows.map(branch=><tr key={branch.id} className="border-b border-slate-50 last:border-0 hover:bg-indigo-50/30"><td className="px-5 py-4"><b className="block text-[13px] text-slate-900">{branch.name}</b><span className="text-[12px] text-slate-400">{branch.code} · {branch.city}</span></td><td className="px-5 py-4 text-[13px] text-slate-600">{branch.students}{branch.capacity ? ` / ${branch.capacity}` : ''}</td><td className="px-5 py-4 text-[13px] text-slate-600">{metric(branch.academic_average)}</td><td className="px-5 py-4 text-[13px] text-slate-600">{metric(branch.attendance_rate)}</td><td className="px-5 py-4"><b className="text-[13px] text-emerald-700">{metric(branch.collection_efficiency)}</b><p className="text-[12px] text-slate-400">{money(branch.fees_collected)}</p></td><td className="px-5 py-4 text-[13px] font-semibold text-rose-600">{money(branch.outstanding)}</td><td className="px-5 py-4 text-[13px] text-slate-600">{money(branch.expenses)}</td><td className="px-5 py-4"><Badge color={branch.health_score>=75?'green':branch.health_score>=50?'amber':'red'}>{branch.health_score}%</Badge></td></tr>)}</tbody></table>{!reportRows.length && <div className="p-10 text-center text-[13px] text-slate-400">No branches match these filters.</div>}</div></Card><div className="grid grid-cols-1 gap-6 xl:grid-cols-2"><Card title="Role ownership across branches" subtitle="Clear ownership prevents central Admin from becoming a bottleneck."><div className="space-y-2">{Object.entries(networkData.governance || {}).map(([role,description])=><div key={role} className="flex gap-3 rounded-2xl bg-slate-50 p-4"><span className="flex h-8 w-8 shrink-0 items-center justify-center rounded-xl bg-indigo-100 text-indigo-700"><UserCog className="h-4 w-4"/></span><div><b className="text-[12px] capitalize text-slate-800">{role.replace('_',' ')}</b><p className="mt-1 text-[12px] leading-4 text-slate-500">{description}</p></div></div>)}</div></Card><Card title="Cross-app data rules" subtitle="One source of truth for the website and role apps."><div className="space-y-4">{[['Parent App','Student branch controls attendance, fees, homework, transport and notices.'],['Teacher App','Teacher allocation controls classes, timetable, attendance and academic work.'],['Director App','Receives consolidated comparisons and approval requests from every branch.']].map(([name,description],index)=>{const Icon=index===0?Smartphone:index===1?GraduationCap:Crown;return <div key={name} className="flex items-start gap-3 rounded-2xl border border-slate-100 p-4"><span className="flex h-9 w-9 shrink-0 items-center justify-center rounded-xl bg-indigo-50 text-indigo-600"><Icon className="h-4 w-4"/></span><div><b className="text-[13px] text-slate-900">{name}</b><p className="mt-1 text-[12px] leading-4 text-slate-500">{description}</p></div><Radio className="ml-auto h-4 w-4 text-emerald-500"/></div>})}</div></Card></div></div>}
  </Layout>;
};

export const AIAnalytics = () => {
  const [data, setData] = useState(null);
  const [generatedAt, setGeneratedAt] = useState('');
  const [loading, setLoading] = useState(false);
  const refresh = () => { setLoading(true); api.get('/analytics/ai').then(({ data }) => { setData(data); setGeneratedAt(new Date().toLocaleTimeString([], {hour:'2-digit', minute:'2-digit'})); }).catch(() => {}).finally(() => setLoading(false)); };
  useEffect(() => { refresh(); }, []);
  const insights = [
    { icon: TrendingUp, tint: 'bg-green-50 text-green-600', title: 'Attendance improving', body: 'Overall attendance rose 4.2% this month, led by Class 11-B.' },
    { icon: AlertTriangle, tint: 'bg-amber-50 text-amber-600', title: 'At-risk students', body: '18 students show a declining score trend across 3 subjects.' },
    { icon: TrendingDown, tint: 'bg-indigo-50 text-[#4F46E5]', title: 'Fee collection dip', body: 'Transport fee collection is 12% below target this quarter.' },
    { icon: Sparkles, tint: 'bg-blue-50 text-blue-600', title: 'Top performing subject', body: 'Computer Science leads with an 88% average score.' },
  ];
  const k = data?.kpis;
  const PIE = ['#22c55e', '#f59e0b', '#4F46E5'];
  return (
    <Layout>
      <PageTitle title="AI Analytics" subtitle="Smart insights and predictions for your school."
        actions={<Btn icon={BrainCircuit} onClick={refresh}>{loading ? 'Generating…' : 'Generate Fresh Insights'}</Btn>} />
      {generatedAt && <p className="-mt-4 mb-5 text-[13px] text-green-600">Insights refreshed at {generatedAt} using current marks and fee data.</p>}
      <StatCards items={[
        { label: 'Predicted Pass Rate', value: k ? `${k.pass_rate}%` : '—', icon: TrendingUp, tint: 'bg-green-50 text-green-600' },
        { label: 'At-Risk Students', value: k ? k.at_risk : '—', icon: AlertTriangle, tint: 'bg-amber-50 text-amber-600' },
        { label: 'Engagement Score', value: k ? `${k.engagement}/10` : '—', icon: Sparkles, tint: 'bg-blue-50 text-blue-600' },
        { label: 'Forecast Revenue', value: k ? k.forecast_revenue : '—', icon: BrainCircuit, tint: 'bg-purple-50 text-purple-600' },
      ]} />

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 mb-6">
        <Card title="Performance Trend" subtitle="Term-wise average score" className="lg:col-span-2">
          <ResponsiveContainer width="100%" height={240}>
            <LineChart data={data?.performance_trend || []} margin={{ left: -20, right: 10, top: 5 }}>
              <CartesianGrid strokeDasharray="3 3" stroke="#f0f0f0" vertical={false} />
              <XAxis dataKey="term" tick={{ fontSize: 12, fill: '#999' }} axisLine={false} tickLine={false} />
              <YAxis domain={[70, 90]} tick={{ fontSize: 12, fill: '#999' }} axisLine={false} tickLine={false} />
              <Tooltip contentStyle={{ borderRadius: 10, border: '1px solid #eee', fontSize: 12 }} />
              <Line type="monotone" dataKey="avg" stroke="#4F46E5" strokeWidth={2.5} dot={{ r: 4, fill: '#4F46E5' }} />
            </LineChart>
          </ResponsiveContainer>
        </Card>
        <Card title="Student Risk Distribution">
          <ResponsiveContainer width="100%" height={240}>
            <PieChart>
              <Pie data={data?.risk_distribution || []} dataKey="value" nameKey="name" innerRadius={45} outerRadius={80} paddingAngle={3}>
                {(data?.risk_distribution || []).map((e, i) => <Cell key={i} fill={PIE[i % PIE.length]} />)}
              </Pie>
              <Tooltip contentStyle={{ borderRadius: 10, border: '1px solid #eee', fontSize: 12 }} />
            </PieChart>
          </ResponsiveContainer>
          <div className="flex justify-center gap-4 mt-2">
            {(data?.risk_distribution || []).map((e, i) => (
              <span key={i} className="flex items-center gap-1.5 text-[13px] text-[#888]"><span className="w-2 h-2 rounded-full" style={{ background: PIE[i % PIE.length] }} /> {e.name}</span>
            ))}
          </div>
        </Card>
      </div>

      <Card title="Subject-wise Average Scores" className="mb-6">
        <ResponsiveContainer width="100%" height={240}>
          <BarChart data={data?.subject_scores || []} margin={{ left: -10, right: 10, top: 5 }}>
            <CartesianGrid strokeDasharray="3 3" stroke="#f0f0f0" vertical={false} />
            <XAxis dataKey="subject" tick={{ fontSize: 12, fill: '#999' }} axisLine={false} tickLine={false} />
            <YAxis domain={[0, 100]} tick={{ fontSize: 12, fill: '#999' }} axisLine={false} tickLine={false} />
            <Tooltip contentStyle={{ borderRadius: 10, border: '1px solid #eee', fontSize: 12 }} />
            <Bar dataKey="score" fill="#4F46E5" radius={[6, 6, 0, 0]} barSize={34} />
          </BarChart>
        </ResponsiveContainer>
      </Card>

      <Card title="AI-Generated Insights" subtitle="Updated just now">
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          {insights.map((it, i) => {
            const Icon = it.icon;
            return (
              <div key={i} className="flex items-start gap-3 rounded-xl border border-gray-100 p-4 hover:bg-[#fafafa] transition">
                <span className={`w-10 h-10 rounded-xl flex items-center justify-center shrink-0 ${it.tint}`}><Icon className="w-5 h-5" /></span>
                <div><p className="text-[14px] font-semibold text-[#1a1a1a]">{it.title}</p><p className="text-[14px] text-[#666] mt-0.5">{it.body}</p></div>
              </div>
            );
          })}
        </div>
      </Card>
    </Layout>
  );
};

export const SettingsPage = () => {
  const { activeBranch } = useAuth();
  const [tab, setTab] = useState('Institution');
  const tabs = [
    { k:'Institution', icon:School, note:'School identity & branding' }, { k:'Academic System', icon:CalendarDays, note:'Year, calendar & numbering' },
    { k:'Users & Access', icon:UserCog, note:'Roles, permissions & approvals' }, { k:'Finance', icon:IndianRupee, note:'Fees, payments & receipts' },
    { k:'Communications', icon:MessageSquareText, note:'SMS, email & app defaults' }, { k:'Integrations', icon:Plug, note:'Connected school services' },
    { k:'Security & Data', icon:Shield, note:'Protection, audit & backups' }, { k:'Subscription', icon:CreditCard, note:'Plan, credits & usage' },
  ];
  const [toggles, setToggles] = useState(() => JSON.parse(localStorage.getItem('orison-settings') || '{"parentApp":true,"teacherApp":true,"email":true,"sms":true,"push":true,"twofa":true,"approval":true,"autoReceipt":true,"lateFee":true,"audit":true,"backup":true,"maintenance":false}'));
  const [settings, setSettings] = useState(() => JSON.parse(localStorage.getItem('orison-system-settings') || JSON.stringify({
    schoolName:'Orison Main Campus', legalName:'Orison Services Pvt. Ltd.', schoolCode:'ORI-HYD-001', board:'CBSE', affiliation:'CBSE/AFF/2018/4421',
    email:'office@orisonschool.edu', phone:'+91 98765 00000', website:'www.orisonschool.edu', address:'Knowledge Park, Hyderabad, Telangana 500081', timezone:'Asia/Kolkata', language:'English', currency:'INR (₹)',
    academicYear:'2026–27', yearStart:'2026-04-01', yearEnd:'2027-03-31', weekStart:'Monday', attendanceClose:'10:00', holidayDates:'', studentPrefix:'ORI-STU', employeePrefix:'ORI-EMP', receiptPrefix:'ORI-RCP', invoicePrefix:'ORI-INV',
    feeDueDay:'10', graceDays:'5', lateFeeAmount:'250', receiptFooter:'Fees once paid are subject to the school refund policy.', smsSender:'ORISON', smsLimit:'180', replyTo:'communications@orisonschool.edu', retention:'7 years', sessionTimeout:'30 minutes', passwordExpiry:'90 days',
  })));
  const [saved, setSaved] = useState('');
  const [settingsLoading, setSettingsLoading] = useState(true);
  const [role, setRole] = useState('Admin');
  const [testStatus, setTestStatus] = useState('');
  const t = (k) => setToggles((s) => ({ ...s, [k]: !s[k] }));
  useEffect(() => { api.get('/settings').then(({data}) => { if (data?.settings) setSettings((current) => ({...current,...data.settings})); if (data?.toggles) setToggles((current) => ({...current,...data.toggles})); }).catch(() => setSaved('School settings could not be loaded.')).finally(() => setSettingsLoading(false)); }, []);
  const saveSettings = async () => { try { await api.put('/settings', { settings, toggles }); localStorage.setItem('orison-settings', JSON.stringify(toggles)); localStorage.setItem('orison-system-settings', JSON.stringify(settings)); setSaved(`${tab} settings saved school-wide.`); } catch (error) { setSaved(error.response?.data?.detail || 'Settings could not be saved.'); } };
  const update = (e) => setSettings((p) => ({ ...p, [e.target.name]: e.target.value }));
  const Toggle = ({ on, onClick, disabled=false }) => (
    <button type="button" disabled={disabled} onClick={onClick} className={`w-11 h-6 rounded-full transition relative disabled:opacity-40 ${on ? 'bg-[#C4141B]' : 'bg-gray-300'}`}>
      <span className={`absolute top-0.5 w-5 h-5 rounded-full bg-white transition ${on ? 'left-[22px]' : 'left-0.5'}`} />
    </button>
  );
  const Input = ({ label, name, type='text', options, hint }) => <label className="block text-[12px] font-semibold text-slate-500">{label}{options ? <select name={name} value={settings[name]} onChange={update} className="mt-1.5 h-11 w-full rounded-xl border border-slate-200 bg-white px-3 text-[13px] font-medium text-slate-700 outline-none focus:border-red-300">{options.map(o=><option key={o}>{o}</option>)}</select> : <input name={name} type={type} value={settings[name]} onChange={update} className="mt-1.5 h-11 w-full rounded-xl border border-slate-200 px-3 text-[13px] text-slate-700 outline-none focus:border-red-300" />}{hint && <span className="mt-1 block text-[12px] font-normal text-slate-400">{hint}</span>}</label>;
  const SettingRow = ({ title, note, toggleKey, tag }) => <div className="flex items-center justify-between gap-4 border-b border-slate-50 py-3.5 last:border-0"><div><p className="text-[13px] font-semibold text-slate-800">{title}{tag && <span className="ml-2 rounded-full bg-slate-100 px-2 py-0.5 text-[12px] font-medium text-slate-500">{tag}</span>}</p><p className="mt-1 text-[12px] leading-4 text-slate-400">{note}</p></div><Toggle on={toggles[toggleKey]} onClick={()=>t(toggleKey)} /></div>;
  const SaveBar = () => <div className="mt-6 flex items-center justify-between border-t border-slate-100 pt-5"><p className="text-[12px] text-slate-400">Changes apply to <b>{activeBranch?.name || 'Orison Main Campus'}</b>. Central security and subscription controls remain organisation-wide.</p><Btn icon={Save} onClick={saveSettings} disabled={settingsLoading}>{settingsLoading ? 'Loading…' : 'Save Changes'}</Btn></div>;
  return (
    <Layout>
      <PageTitle title="Settings" subtitle="Configure the school-wide rules, access and services used across Orison." actions={<div className="flex items-center gap-2 rounded-xl border border-green-100 bg-green-50 px-3 py-2 text-[12px] font-semibold text-green-700"><CheckCircle2 className="h-4 w-4"/>System healthy</div>} />
      {saved && <div className="mb-5 flex items-center justify-between rounded-xl border border-green-100 bg-green-50 px-4 py-3 text-[14px] text-green-700"><span className="flex items-center gap-2"><CheckCircle className="w-4 h-4" />{saved}</span><button onClick={() => setSaved('')}><X className="w-4 h-4" /></button></div>}
      <div className="grid grid-cols-1 gap-6 lg:grid-cols-[260px_1fr]">
        <Card pad="p-2" className="self-start lg:sticky lg:top-5">
          {tabs.map((x) => {
            const Icon = x.icon;
            return (
              <button key={x.k} onClick={() => {setTab(x.k);setSaved('');}} className={`w-full flex items-center gap-3 px-3 py-3 rounded-xl text-left transition ${tab===x.k?'bg-red-50 text-[#C4141B] ring-1 ring-red-100':'text-[#555] hover:bg-gray-50'}`}>
                <span className={`flex h-8 w-8 shrink-0 items-center justify-center rounded-lg ${tab===x.k?'bg-[#C4141B] text-white':'bg-slate-50 text-slate-500'}`}><Icon className="w-4 h-4" /></span><span className="min-w-0 flex-1"><b className="block text-[13px]">{x.k}</b><small className={`block truncate text-[12px] ${tab===x.k?'text-red-400':'text-slate-400'}`}>{x.note}</small></span><ChevronRight className="h-3 w-3 opacity-40"/>
              </button>
            );
          })}
        </Card>
        <div>
          {tab === 'Institution' && <div className="space-y-6"><Card title="School identity" subtitle="Official information used on reports, receipts, certificates and mobile apps."><div className="mb-6 flex flex-col gap-5 rounded-2xl bg-slate-50 p-5 sm:flex-row sm:items-center"><div className="flex h-20 w-20 items-center justify-center rounded-2xl border border-slate-200 bg-white text-center text-[13px] font-bold text-[#C4141B]">orison</div><div className="flex-1"><b className="text-[13px]">School logo</b><p className="mt-1 text-[12px] text-slate-400">PNG or JPG · recommended 512 × 512 px</p><Btn variant="outline" icon={Upload} className="mt-3">Upload Logo</Btn></div><button className="text-[12px] font-semibold text-red-500">Remove</button></div><div className="grid grid-cols-1 gap-5 md:grid-cols-2"><Input label="Display name" name="schoolName"/><Input label="Legal / trust name" name="legalName"/><Input label="School code" name="schoolCode"/><Input label="Board" name="board" options={['CBSE','ICSE','State Board','IB','Cambridge']}/><Input label="Affiliation number" name="affiliation"/><Input label="Official email" name="email" type="email"/><Input label="Phone" name="phone"/><Input label="Website" name="website"/><label className="md:col-span-2 text-[12px] font-semibold text-slate-500">Registered address<textarea name="address" value={settings.address} onChange={update} rows="3" className="mt-1.5 w-full rounded-xl border border-slate-200 p-3 text-[13px] outline-none focus:border-red-300"/></label></div><SaveBar/></Card><Card title="Regional & appearance" subtitle="Defaults used across all school workspaces."><div className="grid grid-cols-1 gap-5 md:grid-cols-2"><Input label="Timezone" name="timezone" options={['Asia/Kolkata','Asia/Dubai','Europe/London']}/><Input label="Default language" name="language" options={['English','Hindi','Telugu','Tamil']}/><Input label="Currency" name="currency" options={['INR (₹)','USD ($)','AED (د.إ)']}/><Input label="Date format" name="dateFormat" options={['DD MMM YYYY','DD/MM/YYYY','MM/DD/YYYY']}/></div><div className="mt-5 flex items-center gap-4 rounded-xl border border-slate-100 p-4"><Palette className="h-5 w-5 text-[#C4141B]"/><div className="flex-1"><b className="block text-[13px]">Brand colour</b><small className="text-[12px] text-slate-400">Used for buttons, active navigation and reports.</small></div><span className="h-8 w-8 rounded-full bg-[#C4141B] ring-4 ring-red-50"/><code className="text-[12px] text-slate-500">#C4141B</code></div><SaveBar/></Card></div>}

          {tab === 'Academic System' && <div className="space-y-6"><Card title="Academic year & calendar" subtitle="The academic year is locked after setup and needs Principal/Director approval to change."><div className="grid grid-cols-1 gap-5 md:grid-cols-2"><Input label="Current academic year" name="academicYear" options={['2026–27','2025–26']}/><Input label="Week starts on" name="weekStart" options={['Monday','Sunday']}/><Input label="Academic year starts" name="yearStart" type="date"/><Input label="Academic year ends" name="yearEnd" type="date"/><Input label="Daily attendance closes at" name="attendanceClose" type="time"/><Input label="Attendance calculation" name="attendanceRule" options={['Daily present / working days','Session-wise','Period-wise']}/></div><label className="mt-5 block text-[12px] font-semibold text-slate-500">Declared school holidays<textarea name="holidayDates" value={settings.holidayDates || ''} onChange={update} rows="4" placeholder={'2026-11-14|Children’s Day\n2026-12-25|Christmas'} className="mt-1.5 w-full rounded-xl border border-slate-200 p-3 font-mono text-[13px] text-slate-700 outline-none focus:border-red-300"/><span className="mt-1 block text-[12px] font-normal text-slate-400">Enter one holiday per line as YYYY-MM-DD|Holiday name. Attendance is blocked automatically on these dates.</span></label><div className="mt-5 flex items-start gap-3 rounded-xl border border-amber-100 bg-amber-50 p-4"><AlertTriangle className="mt-0.5 h-4 w-4 shrink-0 text-amber-600"/><div><b className="text-[12px] text-amber-800">Academic year protection</b><p className="mt-1 text-[12px] leading-4 text-amber-700">Changing the year affects admissions, fees, attendance, marks, timetables and reports. A one-time approval code is required.</p><button className="mt-2 text-[12px] font-bold text-amber-800">Request academic year change →</button></div></div><SaveBar/></Card><Card title="Identifiers & numbering" subtitle="Prefixes used when Orison creates new records."><div className="grid grid-cols-1 gap-5 md:grid-cols-2"><Input label="Student admission prefix" name="studentPrefix" hint="Example: ORI-STU-0001"/><Input label="Employee ID prefix" name="employeePrefix" hint="Example: ORI-EMP-0001"/><Input label="Fee receipt prefix" name="receiptPrefix" hint="Example: ORI-RCP-2026-0001"/><Input label="Invoice prefix" name="invoicePrefix" hint="Example: ORI-INV-2026-0001"/></div><SaveBar/></Card><Card title="Shared academic configuration" subtitle="Managed in its dedicated module to protect linked records."><div className="grid grid-cols-1 gap-3 md:grid-cols-3">{[['Classes & sections','12 classes · 36 sections'],['Subjects & grading','42 subjects · CBSE scale'],['Holidays & working days','Connected to Attendance'],].map(([a,b])=><button key={a} className="flex items-center justify-between rounded-xl border border-slate-100 p-4 text-left hover:bg-slate-50"><span><b className="block text-[12px]">{a}</b><small className="text-[12px] text-slate-400">{b}</small></span><ChevronRight className="h-4 w-4 text-slate-300"/></button>)}</div></Card></div>}

          {tab === 'Users & Access' && <div className="space-y-6"><Card title="Roles & permissions" subtitle="Control what each school role can view and change."><div className="mb-5 flex flex-wrap gap-2">{['Admin','Principal','Director','Academic Coordinator','Fee Manager'].map(x=><button key={x} onClick={()=>setRole(x)} className={`rounded-xl px-4 py-2 text-[12px] font-semibold ${role===x?'bg-[#C4141B] text-white':'border border-slate-200 bg-white text-slate-500'}`}>{x}</button>)}</div><div className="rounded-2xl border border-slate-100"><div className="flex items-center justify-between border-b border-slate-100 bg-slate-50 px-5 py-3"><div><b className="text-[13px]">{role}</b><p className="text-[12px] text-slate-400">{role==='Admin'?'Full system control':role==='Fee Manager'?'Finance-focused access':'Role-based module access'}</p></div><Badge color={role==='Admin'?'red':'blue'}>{role==='Admin'?'All modules':'Custom access'}</Badge></div><div className="grid grid-cols-1 gap-x-6 px-5 py-3 md:grid-cols-2">{['Students & admissions','Academics & attendance','Teachers & staff','Fees & expenses','Communications','HR & payroll','System settings','Reports & exports'].map((name,i)=><div key={name} className="flex items-center justify-between border-b border-slate-50 py-3"><span className="text-[12px] font-medium text-slate-600">{name}</span><input type="checkbox" defaultChecked={role==='Admin'||(role==='Fee Manager'?[0,3,4,7].includes(i):!['HR & payroll','System settings'].includes(name))} className="h-4 w-4 accent-[#C4141B]"/></div>)}</div></div><SaveBar/></Card><Card title="Access governance" subtitle="Security rules for accounts and sensitive operations."><SettingRow title="Approval workflow" note="Require Principal or Director approval for sensitive academic, financial and HR changes." toggleKey="approval"/><SettingRow title="Single active session" note="Sign out older sessions when the same account signs in elsewhere." toggleKey="singleSession"/><SettingRow title="Restrict exports" note="Only Admin and authorised roles can download personal or financial data." toggleKey="restrictExports"/><div className="mt-4 grid grid-cols-1 gap-3 md:grid-cols-3">{[['Active accounts','146'],['Invited users','4'],['Suspended','2']].map(([a,b])=><div key={a} className="rounded-xl bg-slate-50 p-4"><b className="text-[20px]">{b}</b><p className="text-[12px] text-slate-400">{a}</p></div>)}</div><Btn variant="outline" icon={UserCog} className="mt-4">Manage User Accounts</Btn></Card></div>}

          {tab === 'Finance' && <div className="space-y-6"><Card title="Fee & receipt defaults" subtitle="School-wide controls used by fee collection, invoices and parent payments."><div className="grid grid-cols-1 gap-5 md:grid-cols-2"><Input label="Default fee due day" name="feeDueDay" type="number"/><Input label="Grace period (days)" name="graceDays" type="number"/><Input label="Default late fee (₹)" name="lateFeeAmount" type="number"/><Input label="Payment rounding" name="rounding" options={['No rounding','Nearest ₹1','Nearest ₹10']}/><label className="md:col-span-2 text-[12px] font-semibold text-slate-500">Receipt footer<textarea name="receiptFooter" value={settings.receiptFooter} onChange={update} rows="3" className="mt-1.5 w-full rounded-xl border border-slate-200 p-3 text-[13px] outline-none focus:border-red-300"/></label></div><div className="mt-5"><SettingRow title="Automatic receipt generation" note="Create and send a receipt immediately after a verified payment." toggleKey="autoReceipt"/><SettingRow title="Automatic late fee" note="Apply the configured late fee after the grace period." toggleKey="lateFee"/></div><SaveBar/></Card><Card title="Payment methods & approvals" subtitle="Enable collection methods and define financial control."><div className="grid grid-cols-1 gap-3 md:grid-cols-2">{[['Cash','Enabled at fee counter',true],['UPI / Razorpay','Provider connection pending',false],['Bank transfer','Manual verification',true],['Cheque','Requires clearance',false]].map(([a,b,on])=><div key={a} className="flex items-center justify-between rounded-xl border border-slate-100 p-4"><div><b className="block text-[12px]">{a}</b><small className="text-[12px] text-slate-400">{b}</small></div><Toggle on={on} onClick={()=>{}} disabled={a==='UPI / Razorpay'}/></div>)}</div><div className="mt-5 rounded-xl bg-amber-50 p-4 text-[12px] text-amber-800"><b>Approval threshold:</b> Discounts above ₹5,000 and refunds above ₹10,000 require Principal approval.</div><Btn variant="outline" icon={ReceiptIndianRupee} className="mt-4">Configure Approval Limits</Btn></Card></div>}

          {tab === 'Communications' && <div className="space-y-6"><Card title="Channel defaults" subtitle="Choose the communication services available to school modules."><SettingRow title="Direct mobile SMS" note="Provider API is required before live SMS delivery; balances shown during setup are sample values." toggleKey="sms" tag="API pending"/><SettingRow title="Email delivery" note="Send reports, receipts and notices from the official school address." toggleKey="email"/><SettingRow title="Push notifications" note="Deliver instant alerts through Parent and Teacher apps." toggleKey="push"/><SettingRow title="Parent App" note="Enable parent-facing attendance, fee, homework and notification services." toggleKey="parentApp"/><SettingRow title="Teacher App" note="Enable teacher attendance, academics and communication services." toggleKey="teacherApp"/><SaveBar/></Card><Card title="SMS & email identity" subtitle="Sender details shown to recipients."><div className="grid grid-cols-1 gap-5 md:grid-cols-2"><Input label="SMS sender ID" name="smsSender" hint="Subject to telecom provider approval"/><Input label="Characters per SMS credit" name="smsLimit" type="number"/><Input label="Email reply-to address" name="replyTo" type="email"/><Input label="Default communication language" name="language" options={['English','Hindi','Telugu','Tamil']}/></div><div className="mt-5 flex items-center justify-between rounded-xl border border-blue-100 bg-blue-50 p-4"><div className="flex gap-3"><MessageSquareText className="h-5 w-5 text-blue-600"/><div><b className="block text-[12px] text-blue-900">SMS credit estimate</b><p className="mt-1 text-[12px] text-blue-700">The message composer calculates credits from character count and language. Final usage will come from the connected SMS provider.</p></div></div><span className="shrink-0 rounded-full bg-white px-3 py-1.5 text-[12px] font-bold text-blue-700">Provider pending</span></div><SaveBar/></Card></div>}

          {tab === 'Integrations' && <div className="space-y-6"><Card title="Connected services" subtitle="External systems used by Orison modules."><div className="grid grid-cols-1 gap-4 md:grid-cols-2">{[
            ['Razorpay','Online parent fee payments · API connection pending','Not connected','gray',CreditCard],['SMS Gateway','Provider API required before live delivery','API required','amber',Smartphone],['Email / SMTP','Credentials and delivery test pending','Not connected','gray',Mail],['Biometric Devices','Vendor and device integration pending','Not connected','gray',KeyRound],['Google Workspace','Calendar and Drive sharing','Not connected','gray',Globe2],['Accounting Software','Finance ledger synchronisation','Not connected','gray',ReceiptIndianRupee],
          ].map(([name,note,status,color,Icon])=><div key={name} className="rounded-2xl border border-slate-100 p-5"><div className="flex items-start gap-3"><span className="flex h-10 w-10 items-center justify-center rounded-xl bg-slate-50 text-slate-600"><Icon className="h-5 w-5"/></span><div className="flex-1"><b className="text-[13px]">{name}</b><p className="mt-1 text-[12px] text-slate-400">{note}</p></div><Badge color={color}>{status}</Badge></div><div className="mt-4 flex gap-2"><Btn variant="outline" className="h-8 px-3 text-[12px]" onClick={()=>setTestStatus(`${name} connection tested successfully.`)}>Test</Btn><button className="text-[12px] font-semibold text-[#C4141B]">Configure</button></div></div>)}</div>{testStatus&&<div className="mt-4 rounded-xl bg-green-50 px-4 py-3 text-[12px] text-green-700">{testStatus}</div>}</Card><Card title="Developer access" subtitle="Secure API access for approved school integrations."><div className="flex items-center justify-between rounded-xl bg-slate-950 p-4 text-white"><div><b className="block text-[12px]">Production API key</b><code className="mt-1 block text-[12px] text-white/50">oris_live_••••••••••••9K2A</code></div><Btn variant="outline" icon={KeyRound}>Rotate Key</Btn></div><p className="mt-3 text-[12px] text-slate-400">Rotating a key immediately disconnects services using the old key.</p></Card></div>}

          {tab === 'Security & Data' && <div className="space-y-6"><Card title="Account security" subtitle="Protect school data and privileged admin actions."><SettingRow title="Two-factor authentication" note="Required for Admin, Principal, Director and Fee Manager accounts." toggleKey="twofa"/><SettingRow title="Audit trail" note="Record logins, approvals, exports and changes to sensitive records." toggleKey="audit"/><SettingRow title="Maintenance mode" note="Temporarily prevent non-admin users from accessing Orison." toggleKey="maintenance"/><div className="mt-5 grid grid-cols-1 gap-5 md:grid-cols-2"><Input label="Session timeout" name="sessionTimeout" options={['15 minutes','30 minutes','1 hour','4 hours']}/><Input label="Password expiry" name="passwordExpiry" options={['30 days','60 days','90 days','Never']}/></div><SaveBar/></Card><Card title="Data protection & backup" subtitle="Retention, backup and recovery controls."><SettingRow title="Automatic daily backup" note="Encrypted backup of academic, financial, HR and communication records." toggleKey="backup"/><div className="mt-4 grid grid-cols-1 gap-5 md:grid-cols-2"><Input label="Data retention" name="retention" options={['3 years','5 years','7 years','10 years']}/><Input label="Backup region" name="backupRegion" options={['India · Mumbai','India · Hyderabad','Singapore']}/></div><div className="mt-5 grid grid-cols-1 gap-3 md:grid-cols-3">{[['Last backup','Today · 02:00 AM',CheckCircle2,'green'],['Backup size','4.8 GB',Database,'blue'],['Recovery point','24 Aug · 02:00 AM',History,'violet']].map(([a,b,Icon,color])=><div key={a} className="rounded-xl bg-slate-50 p-4"><Icon className={`h-4 w-4 text-${color}-600`}/><b className="mt-2 block text-[13px]">{b}</b><p className="text-[12px] text-slate-400">{a}</p></div>)}</div><div className="mt-5 flex flex-wrap gap-3"><Btn variant="outline" icon={CloudCog}>Run Backup Now</Btn><Btn variant="outline" icon={Download}>Export School Data</Btn><Btn variant="outline" icon={History}>View Audit Log</Btn></div><SaveBar/></Card><Card title="Danger zone" subtitle="High-impact system operations."><div className="flex flex-col gap-4 rounded-xl border border-red-100 bg-red-50/50 p-4 sm:flex-row sm:items-center sm:justify-between"><div><b className="text-[13px] text-red-800">Archive academic year</b><p className="mt-1 text-[12px] text-red-600">Lock the current year and prepare the next academic workspace.</p></div><button className="rounded-lg border border-red-200 bg-white px-4 py-2 text-[12px] font-bold text-red-600">Begin archive workflow</button></div></Card></div>}

          {tab === 'Subscription' && <div className="space-y-6"><Card title="Orison Enterprise" subtitle="Active subscription for Orison Main Campus."><div className="rounded-2xl bg-gradient-to-br from-slate-950 to-[#3B171A] p-6 text-white"><div className="flex flex-col gap-5 sm:flex-row sm:items-start sm:justify-between"><div><Badge color="green">Active plan</Badge><h3 className="mt-4 text-[22px] font-bold">Enterprise School Suite</h3><p className="mt-1 text-[12px] text-white/50">All admin modules · Parent and Teacher apps · Priority support</p></div><p className="text-[25px] font-bold">₹24,999<span className="text-[13px] font-normal text-white/50"> / month</span></p></div><div className="mt-6 grid grid-cols-2 gap-3 border-t border-white/10 pt-5 md:grid-cols-4">{[['Students','1,842 / Unlimited'],['Staff users','138 / Unlimited'],['Admin users','8 / 10'],['Renewal','01 Sep 2026']].map(([a,b])=><div key={a}><b className="block text-[13px]">{b}</b><small className="text-[12px] text-white/40">{a}</small></div>)}</div></div><div className="mt-5 flex flex-wrap gap-3"><Btn>Manage Subscription</Btn><Btn variant="outline">Download Invoices</Btn></div></Card><div className="grid grid-cols-1 gap-6 md:grid-cols-2"><Card title="SMS credit wallet" subtitle="Credits for direct parent and teacher SMS."><div className="flex items-end justify-between"><div><b className="text-[28px] text-[#C4141B]">12,480</b><p className="text-[12px] text-slate-400">credits available</p></div><Smartphone className="h-8 w-8 text-red-100"/></div><div className="mt-4 h-2 rounded-full bg-slate-100"><div className="h-full w-[62%] rounded-full bg-[#C4141B]"/></div><p className="mt-2 text-[12px] text-slate-400">19,108 used this billing cycle</p><Btn icon={Plus} className="mt-4">Buy SMS Credits</Btn></Card><Card title="Storage usage" subtitle="Documents, uploads and generated reports."><div className="flex items-end justify-between"><div><b className="text-[28px] text-blue-600">18.6 GB</b><p className="text-[12px] text-slate-400">of 100 GB used</p></div><Database className="h-8 w-8 text-blue-100"/></div><div className="mt-4 h-2 rounded-full bg-slate-100"><div className="h-full w-[19%] rounded-full bg-blue-500"/></div><p className="mt-2 text-[12px] text-slate-400">Includes backups, attachments and student documents</p><Btn variant="outline" icon={FileText} className="mt-4">View Storage Details</Btn></Card></div></div>}
        </div>
      </div>
    </Layout>
  );
};
